import numpy as np
W={'Ag1':(100,130),'Ag2':(225,262),'Ag3':(332,356),'D?300':(290,315),'Si':(500,540)}
for pol in 'ab':
  for s in ['step0_untreated','step1','step2','step3']:
    f=f"{s}_E-along-{pol}.csv"; d=np.loadtxt(f,delimiter=',',skiprows=1); x,y=d.T
    out=[]
    si=None
    for k,(lo,hi) in W.items():
      m=(x>=lo)&(x<=hi); xs,ys=x[m],y[m]
      b=np.linspace(np.median(ys[:3]),np.median(ys[-3:]),len(ys)); c=ys-b
      a=np.trapz(c,xs); 
      if k=='Si': si=a
      out.append((k,round(xs[c.argmax()],1),a))
    print(pol,s,' '.join(f"{k}:pk{p}/A{a/si:.4f}" for k,p,a in out), f"SiA={si:.3f}")
