import numpy as np
W={'Ag1':(100,130),'Ag2':(225,262),'D300':(290,315),'Ag3':(332,356),'Si':(500,540)}
for pol in 'ab':
  for s in ['step0_untreated','step1','step2','step3']:
    f=f"{s}_E-along-{pol}.csv"; d=np.loadtxt(f,delimiter=',',skiprows=1); x,y=d.T
    r={}
    for k,(lo,hi) in W.items():
      m=(x>=lo)&(x<=hi); xs,ys=x[m],y[m]
      b=np.linspace(np.median(ys[:3]),np.median(ys[-3:]),len(ys)); c=ys-b
      r[k]=(xs[c.argmax()],np.trapezoid(c,xs))
    si=r['Si'][1]
    print(pol,s[:5],' '.join(f"{k}:{p:.1f}/{a/si*100:.2f}%" for k,(p,a) in r.items() if k!='Si'),f"SiA={si:.2f}")
